    /// <summary>
    /// Finds a specific <c>WHSPhysDimUOM</c> with given parameters.
    /// </summary>
    /// <param name="_recId">
    /// Id of the record.
    /// </param>
    /// <param name="_forupdate">
    /// Determines whether the record is selected for update.
    /// </param>
    /// <returns>
    /// The record that is searched for.
    /// </returns>
    public static METWHSPhysDimUOMSite findbyRecId(RefRecId _recId, boolean _forupdate = false)
    {
        METWHSPhysDimUOMSite whsPhysDimUOM;

        if (_recId)
        {
            whsPhysDimUOM.selectForUpdate(_forupdate);

            select firstonly whsPhysDimUOM
                where whsPhysDimUOM.RecId == _recId;
        }

        return whsPhysDimUOM;
    }

/// <summary>
/// Checks whether a specific <c>whsPhysDimUOM</c> record exists.
/// </summary>
/// <param name="_recId">
/// The parameter of type <c>RecId</c>.
/// </param>
/// <returns>
/// True if the record exists.
/// </returns>
public static boolean exist(RecId _recId)
{
    return (_recId) &&
           (select firstonly METWHSPhysDimUOMSite
            where METWHSPhysDimUOMSite.RecId == _recId).RecId != 0;
}

    /// <summary>
    ///     Updates the itemId and UOM on the table.
    /// </summary>
    /// <param name="_itemId">
    ///     The item ID.
    /// </param>
    public static void updateItemUOM(ItemId _itemId)
    {
        WHSUOMSeqGroupLine          uomSeqGroupLine;
        WHSUOMSeqGroupId            seqGroupId;
        InventTable                 inventTable;
        WHSInventTable              whsInventTable;
        METWHSPhysDimUOMSite        physDimUOMSiteInsert;
        METWHSPhysDimUOMSite        physDimUOMSiteExists;
        Weight                      grossWeight;
        InventDepth                 grossDepth;
        InventHeight                grossHeight;
        InventWidth                 grossWidth;

        inventTable = InventTable::find(_itemId);
        grossWeight = inventTable.grossWeight();
        grossDepth  = inventTable.grossDepth;
        grossHeight = inventTable.grossHeight;
        grossWidth  = inventTable.grossWidth;        

        insert_recordset physDimUOMSiteInsert (ItemId, uom, Weight, Depth, Height, Width)
        select _itemId, UnitId, grossWeight, grossDepth, grossHeight, grossWidth from uomSeqGroupLine
            exists join whsInventTable
                where whsInventTable.UOMSeqGroupId == uomSeqGroupLine.UOMSeqGroupId &&
                      whsInventTable.ItemId == _itemId
            notexists join physDimUOMSiteExists
                where physDimUOMSiteExists.UOM == uomSeqGroupLine.UnitId &&
                      physDimUOMSiteExists.ItemId   == _itemId;
    }

/// <summary>
/// Display method for the volume from the physical dimensions.
/// </summary>
/// <returns>
/// The volume calculated from physical dimensions.
/// </returns>
public display Volume displayVolume()
{
    return this.Depth * this.Height * this.Width;
}

/// <summary>
/// Display method for the Surface Area M2 from the physical dimensions.
/// </summary>
/// <returns>
/// The Surface Area M2 calculated from physical dimensions.
/// </returns>
public display METSurfaceAreaM2 displaySurfaceAreaM2()
{
    #define.Million(1000000)
    return (this.Depth * this.Width)/#Million;
}

/// <summary>
/// Display method for the Case volume CM from the physical dimensions.
/// </summary>
/// <returns>
/// The Case volume CM calculated from physical dimensions.
/// </returns>
public display METCaseVolM2 displayCaseVolumeCM()
{
    #define.Thousand(1000)
    return (this.Depth / #Thousand) * (this.Height / #Thousand) * (this.Width / #Thousand);
}

    /// <summary>
    /// Calculates the weight for transfer order line based on UOM and Site
    /// </summary>
    /// <param name = "_itemId">ItemId</param>
    /// <param name = "_qty">Quantity</param>
    /// <param name = "_uom">SalesUnitSymbol</param>
    /// <param name = "_inventDim"><c>InventDim</c> buffer</param>
    /// <returns>Return Weight</returns>
    public static Weight convertWeight( ItemId      _itemId,
                                    InventQty       _qty,    
                                    WHSUOM          _uom,
                                    InventDim       _inventDim)
    {
        METWHSPhysDimUOMSite    metWHSPhysDimUOMSite;
        WHSPhysDimUOM           whsPhysDimUOM;
        Factor                  factor;

        Weight                  weight;

        //Find direct UOM weight
        select firstonly weight from metWHSPhysDimUOMSite
            where metWHSPhysDimUOMSite.ItemId == _itemId
            && metWHSPhysDimUOMSite.UOM == _uom
            && metWHSPhysDimUOMSite.SiteId == _inventDim.InventSiteId;

        weight  = _qty * metWHSPhysDimUOMSite.Weight;

        if (!weight)
        {
            //If direct weight is not found, then find available UOM weight
            select firstonly weight, UOM, ItemId from metWHSPhysDimUOMSite
            where metWHSPhysDimUOMSite.ItemId == _itemId
            && metWHSPhysDimUOMSite.SiteId == _inventDim.InventSiteId;

            factor = EcoResProductUnitConverter::convertForReleasedProduct(
                        metWHSPhysDimUOMSite.ItemId,
                        _inventDim.inventDimId,
                        1,
                        EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(metWHSPhysDimUOMSite.UOM),
                        EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(_uom),
                        NoYes::No,
                        NoYes::No);

            if (factor)
            {
                weight = _qty * (metWHSPhysDimUOMSite.Weight/factor);
            }

            if (!weight)
            {
                select firstonly weight from whsPhysDimUOM
                    where whsPhysDimUOM.ItemId == _itemId
                    && whsPhysDimUOM.UOM == _uom;

                weight = _qty * whsPhysDimUOM.Weight;
            }

            if(!weight)
            {
                select firstonly weight, UOM, ItemId from whsPhysDimUOM
                    where whsPhysDimUOM.ItemId == _itemId;

                factor = EcoResProductUnitConverter::convertForReleasedProduct(
                        whsPhysDimUOM.ItemId,
                        _inventDim.inventDimId,
                        1,
                        EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(whsPhysDimUOM.UOM),
                        EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(_uom),
                        NoYes::No,
                        NoYes::No);

                if (factor)
                {
                    weight = _qty * (whsPhysDimUOM.Weight/factor);
                }
            }
        }

        return weight;
    }

    /// <summary>
    /// Calculates the volume for transfer order line based on UOM and Site
    /// </summary>
    /// <param name = "_itemId">ItemId</param>
    /// <param name = "_qty">Quantity</param>
    /// <param name = "_uom">SalesUnitSymbol</param>
    /// <param name = "_inventDim"><c>InventDim</c> buffer</param>
    /// <returns>Return Volume.</returns>
    public static Weight convertVolume( ItemId          _itemId,
                                    InventQty       _qty,
                                    WHSUOM          _uom,
                                    InventDim       _inventDim)
    {
        METWHSPhysDimUOMSite    metWHSPhysDimUOMSite;
        WHSPhysDimUOM           whsPhysDimUOM;
        Factor                  factor;

        Volume                  volume;

        select firstonly * from metWHSPhysDimUOMSite
            where metWHSPhysDimUOMSite.ItemId == _itemId
            && metWHSPhysDimUOMSite.UOM == _uom
            && metWHSPhysDimUOMSite.SiteId == _inventDim.InventSiteId;

        volume  = _qty * metWHSPhysDimUOMSite.displayVolume();

        if (!volume)
        {
            select firstonly * from metWHSPhysDimUOMSite
            where metWHSPhysDimUOMSite.ItemId == _itemId
            && metWHSPhysDimUOMSite.SiteId == _inventDim.InventSiteId;

            factor = EcoResProductUnitConverter::convertForReleasedProduct(
                        metWHSPhysDimUOMSite.ItemId,
                        _inventDim.inventDimId,
                        1,
                        EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(metWHSPhysDimUOMSite.UOM),
                        EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(_uom),
                        NoYes::No,
                        NoYes::No);

            if (factor)
            {
                volume = _qty * (metWHSPhysDimUOMSite.displayVolume()/factor);
            }

            if (!volume)
            {
                select firstonly * from whsPhysDimUOM
                    where whsPhysDimUOM.ItemId == _itemId
                    && whsPhysDimUOM.UOM == _uom;

                volume = _qty * whsPhysDimUOM.displayVolume();
            }

            if(!volume)
            {
                select firstonly * from whsPhysDimUOM
                    where whsPhysDimUOM.ItemId == _itemId;

                factor = EcoResProductUnitConverter::convertForReleasedProduct(
                        whsPhysDimUOM.ItemId,
                        _inventDim.inventDimId,
                        1,
                        EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(whsPhysDimUOM.UOM),
                        EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(_uom),
                        NoYes::No,
                        NoYes::No);

                if (factor)
                {
                    volume = _qty * (whsPhysDimUOM.displayVolume()/factor);
                }
            }
        }

        return volume;
    }
